export interface CLAUDEmdOptions {
  projectName?: string;         // override del nombre del proyecto
  language?: 'en' | 'es';      // default: 'en'
  includeSections?: CLAUDEmdSection[];
  complianceSummary?: boolean;  // default: true
}

export type CLAUDEmdSection =
  | 'overview'
  | 'commands'
  | 'architecture'
  | 'conventions'
  | 'compliance'
  | 'important-notes';

async toCLAUDEmd(options: CLAUDEmdOptions = {}): Promise<string> {
  const output = await this.collectContext();
  const pkgCtx = output.contexts.find(c => c.type === 'package-json');
  const gitCtx = output.contexts.find(c => c.type === 'git');
  const fsCtx = output.contexts.find(c => c.type === 'filesystem');
  const report = output.complianceReport;

  const sections: string[] = [
    buildOverviewSection(pkgCtx, gitCtx, options),
    buildCommandsSection(pkgCtx, options),
    buildArchitectureSection(fsCtx, pkgCtx, options),
    buildConventionsSection(pkgCtx, options),
  ];

  if (report && options.complianceSummary !== false) {
    sections.push(buildComplianceSection(report, options));
  }

  sections.push(buildImportantNotesSection(report, pkgCtx, options));

  return sections.filter(Boolean).join('\n\n');
}

